int main() {
  double tmp1, tmp2;
  std::fstream in("./code/main_fstream_input.txt"); // specify input file

  in &gt;&gt; tmp1; // read first value
  in &gt;&gt; tmp2; // read second value
  std::cout &lt;&lt; tmp1 &lt;&lt; " ";
  std::cout &lt;&lt; tmp2 &lt;&lt; std::endl;

  return 0;
}


